using System;using System.Collections.Generic;using UnityEngine;
namespace FashionFit {
 [DefaultExecutionOrder(300)] public sealed class LayeredAoDai:MonoBehaviour {
  public NativeClothTree PantsTree{get;private set;}public NativeClothTree FrontTree{get;private set;}public NativeClothTree BackTree{get;private set;}public PoseBodyField BodyField=>field;public Bounds[] RoomBounds=>room.ToArray();public RunwayAvatar Avatar{get;private set;}public LayeredPanel Front{get;private set;}public LayeredPanel Back{get;private set;}public BodyBoundSurface Bodice{get;private set;}public BodyBoundSurface Pants{get;private set;}
  public int SelectedLayer{get;private set;}=-1;public float LengthScale{get;private set;}=1;public float WidthScale{get;private set;}=1;public bool ArrangementMode{get;private set;}public double Milliseconds{get;private set;}
  public static readonly string[] Layers={"Tất cả lớp","Thân / tay áo","Tà trước","Tà sau","Quần bên trong"};
  public string LayerLabel=>Layers[SelectedLayer+1];public Matrix4x4 HipMatrix{get;private set;}public Vector3 LocalGravity{get;private set;}
  FashionFitApp app;PoseBodyField field;Matrix4x4 inverseHip,localToWorld,worldToLocal;Matrix4x4[] matrices;int pantsVersion=-1;float accumulator,idle;bool dirty=true;GarmentSurfaceTransfer.Surface pantsContact,frontContact,backContact;
  readonly List<Mesh> ownedMeshes=new List<Mesh>();readonly List<Material> materials=new List<Material>();readonly List<Transform> roots=new List<Transform>();
  readonly List<Bounds> room=new List<Bounds>();Vector3[] oldFront,oldBack;MembraneMaterial profile=MembraneMaterial.Presets[1];string gender;
  public bool IsGrabbed=>(Front&&Front.GrabCount>0)||(Back&&Back.GrabCount>0)||(Bodice&&Bodice.Surface.GrabCount>0)||(Pants&&Pants.Surface.GrabCount>0);
  public void Initialize(FashionFitApp owner,RunwayAvatar avatar,string sex){app=owner;Avatar=avatar;gender=sex;matrices=new Matrix4x4[avatar.Bones.Length];field=new PoseBodyField(sex);foreach(var box in app.GetComponentsInChildren<BoxCollider>())if(box.gameObject.layer==10&&!box.isTrigger)room.Add(box.bounds);Build();}
  Material Fabric(string name,Color color){var material=new Material(Resources.Load<Shader>("Runway/DressFabric")){name=name};material.SetColor("_Color",color);material.SetFloat("_Glossiness",.22f);materials.Add(material);return material;}
  Transform Part(string label,int layer){var go=new GameObject(label);go.transform.SetParent(transform,false);var part=go.AddComponent<GarmentLayerPart>();part.Owner=this;part.Layer=layer;roots.Add(go.transform);return go.transform;}
  void Build(){UpdateFrame();var teal=Fabric("Ao dai teal outer",new Color(.055f,.32f,.32f));var ivory=Fabric("Ao dai ivory trousers",new Color(.82f,.77f,.63f));Mesh top=FittedGarmentGeometry.Shell(Avatar,false,true),pants=FittedGarmentGeometry.Shell(Avatar,true);ownedMeshes.Add(top);ownedMeshes.Add(pants);Bodice=Part("Ao dai bodice and raglan-like sleeves",0).gameObject.AddComponent<BodyBoundSurface>();Bodice.Initialize(Avatar,top,teal,gender);Pants=Part("Ao dai independent trousers",3).gameObject.AddComponent<BodyBoundSurface>();Pants.Initialize(Avatar,pants,ivory,gender);
   Front=MakePanel("Tà trước",1,true,teal);Back=MakePanel("Tà sau",2,false,teal);pantsContact=new GarmentSurfaceTransfer.Surface(Pants.Surface.MeshAt(0).vertices,Pants.Surface.MeshAt(0).triangles);frontContact=new GarmentSurfaceTransfer.Surface(Front.Positions,Front.Faces);backContact=new GarmentSurfaceTransfer.Surface(Back.Positions,Back.Faces);PantsTree=new NativeClothTree(Pants.Surface.MeshAt(0).vertices,Pants.Surface.MeshAt(0).triangles);FrontTree=new NativeClothTree(Front.Positions,Front.Faces);BackTree=new NativeClothTree(Back.Positions,Back.Faces);oldFront=(Vector3[])Front.Positions.Clone();oldBack=(Vector3[])Back.Positions.Clone();SetMaterial(profile,true);dirty=true;idle=0;}
  LayeredPanel MakePanel(string label,int layer,bool front,Material material){const int cols=13,rows=21;float h=Avatar.BodyMesh.bounds.max.y,top=h*.605f,bottom=top-(top-.12f)*LengthScale;var p=new Vector3[cols*rows];var uv=new Vector2[p.Length];var triangles=new List<int>();float rx=.18f,frontZ=.12f,backZ=-.12f;
   foreach(var v in Avatar.BodyVertices)if(Mathf.Abs(v.y-top)<.035f&&Mathf.Abs(v.x)<.27f){rx=Mathf.Max(rx,Mathf.Abs(v.x)+.022f);frontZ=Mathf.Max(frontZ,v.z+.038f);backZ=Mathf.Min(backZ,v.z-.038f);}for(int r=0;r<rows;r++)for(int c=0;c<cols;c++){float u=c/(float)(cols-1),v=r/(float)(rows-1),angle=(u-.5f)*Mathf.PI*.84f,y=Mathf.Lerp(top,bottom,v);float width=rx*WidthScale*(1+.23f*Mathf.SmoothStep(0,1,v)),depth=(front?frontZ:-backZ)+.045f*v;int id=r*cols+c;p[id]=new Vector3(Mathf.Sin(angle)*width,y,(front?1:-1)*Mathf.Lerp(Mathf.Cos(angle),1,Mathf.SmoothStep(0,1,v*.85f))*depth);uv[id]=new Vector2(u,v);if(r<rows-1&&c<cols-1){int a=id,b=id+1,d=id+cols,e=d+1;if(front){triangles.AddRange(new[]{a,d,b,b,d,e});}else triangles.AddRange(new[]{a,b,d,b,e,d});}}
   var panel=Part(label,layer).gameObject.AddComponent<LayeredPanel>();panel.Initialize(this,label,p,uv,triangles.ToArray(),cols,material);return panel;}
  void UpdateFrame(){Avatar.FillSkinMatrices(matrices);HipMatrix=matrices[Avatar.BoneIndex("Hips")];inverseHip=HipMatrix.inverse;localToWorld=Avatar.transform.localToWorldMatrix;worldToLocal=Avatar.transform.worldToLocalMatrix;LocalGravity=worldToLocal.MultiplyVector(Physics.gravity);}
  void LateUpdate(){StepSimulation(Time.deltaTime);}
  public void StepSimulation(float delta){Milliseconds=0;if(!Front||delta<=0)return;accumulator=Mathf.Min(.06f,accumulator+delta);if(accumulator<1f/60)return;var previous=HipMatrix;UpdateFrame();bool moved=false;for(int i=0;i<16;i++)if(Mathf.Abs(previous[i]-HipMatrix[i])>1e-5f)moved=true;if(!dirty&&!IsGrabbed&&!moved)return;var timer=System.Diagnostics.Stopwatch.StartNew();if(pantsVersion!=Pants.Version){pantsContact.Refit(Pants.Surface.CurrentPoints);PantsTree.Refit(Pants.Surface.CurrentPoints);pantsVersion=Pants.Version;}int performed=0;while(accumulator>=1f/60&&performed++<1){accumulator-=1f/60;frontContact.Refit(Front.Positions);FrontTree.Refit(Front.Positions);backContact.Refit(Back.Positions);BackTree.Refit(Back.Positions);Front.Step(1f/60);frontContact.Refit(Front.Positions);FrontTree.Refit(Front.Positions);Back.Step(1f/60);for(int pass=0;pass<2;pass++){backContact.Refit(Back.Positions);BackTree.Refit(Back.Positions);Front.ResolveContacts();frontContact.Refit(Front.Positions);FrontTree.Refit(Front.Positions);Back.ResolveContacts();}}if(accumulator>=1f/60)accumulator=1f/120;Front.Publish();Back.Publish();Milliseconds=timer.Elapsed.TotalMilliseconds;idle=IsGrabbed||moved?0:idle+delta;dirty=idle<7;}
  public Vector3 Contact(Vector3 p,Vector3 previous,LayeredPanel panel){Vector3 q=HipMatrix.MultiplyPoint3x4(field.Project(inverseHip.MultiplyPoint3x4(p)));
   // Contact with actual trouser triangles. Only local surface normal order is
   // used; no global front/back sorting or body masking is applied.
   q=OutsideCloth(q,previous,pantsContact,.012f,true);var other=panel==Front?backContact:frontContact;if(other!=null)q=OutsideCloth(q,previous,other,.010f,false);Vector3 world=localToWorld.MultiplyPoint3x4(q);world.y=Mathf.Max(.014f,world.y);foreach(var b in room)if(b.Contains(world)){Vector3 min=b.min,max=b.max;float best=world.x-min.x;Vector3 result=new Vector3(min.x-.006f,world.y,world.z);float d=max.x-world.x;if(d<best){best=d;result=new Vector3(max.x+.006f,world.y,world.z);}d=world.y-min.y;if(d<best){best=d;result=new Vector3(world.x,min.y-.006f,world.z);}d=max.y-world.y;if(d<best){best=d;result=new Vector3(world.x,max.y+.006f,world.z);}d=world.z-min.z;if(d<best){best=d;result=new Vector3(world.x,world.y,min.z-.006f);}d=max.z-world.z;if(d<best)result=new Vector3(world.x,world.y,max.z+.006f);world=result;}return worldToLocal.MultiplyPoint3x4(world);}
  static Vector3 OutsideCloth(Vector3 p,Vector3 previous,GarmentSurfaceTransfer.Surface surface,float thickness,bool outward){if(surface==null||surface.Bounds.SqrDistance(p)>.002025f)return p;var hit=surface.Nearest(p);int i=hit.triangle*3;Vector3 n=Vector3.Cross(surface.vertices[surface.triangles[i+1]]-surface.vertices[surface.triangles[i]],surface.vertices[surface.triangles[i+2]]-surface.vertices[surface.triangles[i]]).normalized;float signed=Vector3.Dot(p-hit.point,n),old=Vector3.Dot(previous-hit.point,n);float side=outward?1:(old>=0?1:-1);float d=Vector3.Distance(p,hit.point);if(d<thickness){Vector3 radial=p-hit.point;p=hit.point+(radial.sqrMagnitude>1e-10f?radial.normalized:n*side)*thickness;}
   else if(d<.045f&&signed*old<0&&Mathf.Min(hit.barycentric.x,Mathf.Min(hit.barycentric.y,hit.barycentric.z))>.001f)p+=n*(side*(thickness-signed*side));return p;}
  public void SelectLayer(int layer){app.Player.EndActiveGrab();SelectedLayer=Mathf.Clamp(layer,-1,3);dirty=true;app.Report("Lớp chọn: "+LayerLabel+" · các lớp khác vẫn hiển thị và va chạm");}
  public void CycleLayer(){SelectLayer(SelectedLayer==3?-1:SelectedLayer+1);}
  public void SetMaterial(MembraneMaterial material,bool all=false){profile=material;if(Front){if(all||SelectedLayer<0||SelectedLayer==1)Front.Material=material;if(all||SelectedLayer<0||SelectedLayer==2)Back.Material=material;if(all||SelectedLayer<0||SelectedLayer==0)Bodice.Surface.SetMaterial(material);if(all||SelectedLayer<0||SelectedLayer==3)Pants.Surface.SetMaterial(material);}dirty=true;idle=0;}
  public MembraneMaterial Material=>!Front?profile:SelectedLayer==0?Bodice.Surface.Material:SelectedLayer==1?Front.Material:SelectedLayer==2?Back.Material:SelectedLayer==3?Pants.Surface.Material:profile;
  public string Summary=>LayerLabel+" · "+(SelectedLayer==0?Bodice.Surface.Reading.Summary:SelectedLayer==3?Pants.Surface.Reading.Summary:SelectedLayer==2?Back.Reading.Summary:Front.Reading.Summary);
  public void SetDesign(float length,float width){app.Player.EndActiveGrab();LengthScale=Mathf.Clamp(length,.82f,1.12f);WidthScale=Mathf.Clamp(width,.90f,1.16f);var savedFront=Front.Material;var savedBack=Back.Material;var savedTop=Bodice.Surface.Material;var savedPants=Pants.Surface.Material;ClearParts();Build();Front.Material=savedFront;Back.Material=savedBack;Bodice.Surface.SetMaterial(savedTop);Pants.Surface.SetMaterial(savedPants);app.Report("Đổi rập thử: dài "+LengthScale.ToString("F2")+" · rộng "+WidthScale.ToString("F2")+"; thay đổi được giữ sau khi thả");}
  public void ToggleArrangement(){ArrangementMode=!ArrangementMode;app.Report(ArrangementMode?"Xếp tà: giữ hình sau thả; chọn Hồi tự nhiên để trả về độ rủ":"Hồi tự nhiên: tà rơi và hồi theo vật liệu");}
  public void ResetDrape(){app.Player.EndActiveGrab();Front.ResetShape();Back.ResetShape();Bodice.Surface.ResetShape();Pants.Surface.ResetShape();dirty=true;idle=0;}
  public void Wake(){dirty=true;idle=0;}
  void ClearParts(){if(PantsTree!=null){PantsTree.Dispose();PantsTree=null;}if(FrontTree!=null){FrontTree.Dispose();FrontTree=null;}if(BackTree!=null){BackTree.Dispose();BackTree=null;}foreach(var root in roots)if(root){root.gameObject.SetActive(false);if(Application.isPlaying)Destroy(root.gameObject);else DestroyImmediate(root.gameObject);}roots.Clear();foreach(var mesh in ownedMeshes)if(mesh){if(Application.isPlaying)Destroy(mesh);else DestroyImmediate(mesh);}ownedMeshes.Clear();foreach(var material in materials)if(material){if(Application.isPlaying)Destroy(material);else DestroyImmediate(material);}materials.Clear();}
  void OnDestroy(){ClearParts();if(field!=null)field.Dispose();}
 }
